// Some portions generated by Co-Pilot
import {
  act,
  fireEvent,
  render,
  screen,
  waitFor,
  within,
} from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import { loadLatestAssets } from "@/hooks";
import type { TemurinAssets } from "@/types/temurin";
import TemurinReleases from "../releases-client";

const url = vi.hoisted(() => ({
  value: "version=17",
  listeners: new Set<() => void>(),
}));

vi.mock("@/hooks", () => ({ loadLatestAssets: vi.fn() }));
vi.mock("@/hooks/fetchConstants", () => ({
  useOses: () => [
    { name: "Linux", value: "linux" },
    { name: "Windows", value: "windows" },
    { name: "macOS", value: "mac" },
  ],
  useArches: () => [
    { name: "x64", value: "x64" },
    { name: "aarch64", value: "aarch64" },
  ],
}));
vi.mock("@/hooks/useAttestations", () => ({
  useAttestations: () => ({
    attestations: {},
    isLoading: false,
    error: undefined,
  }),
}));
vi.mock("@/utils/setURLParam", () => ({
  setURLParam: vi.fn(
    (name: string, value: string | number | boolean | undefined) => {
      const params = new URLSearchParams(url.value);
      if (value === undefined) params.delete(name);
      else params.set(name, String(value));
      url.value = params.toString();
      url.listeners.forEach((listener) => listener());
    },
  ),
}));
vi.mock("next/navigation", async () => {
  const { useSyncExternalStore } = await import("react");
  return {
    useSearchParams: () => {
      const value = useSyncExternalStore(
        (listener) => {
          url.listeners.add(listener);
          return () => {
            url.listeners.delete(listener);
          };
        },
        () => url.value,
        () => url.value,
      );
      return new URLSearchParams(value);
    },
  };
});

const availableReleases = {
  available_lts_releases: [8, 11, 17, 21, 25],
  most_recent_lts: 25,
  available_releases: [8, 11, 17, 21, 25, 26],
};
const renderPage = () =>
  render(<TemurinReleases availableReleases={availableReleases} />);

describe("Temurin releases page", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    url.value = "version=17";
    vi.mocked(loadLatestAssets).mockResolvedValue([]);
  });
  afterEach(() => vi.restoreAllMocks());

  it("renders correctly", async () => {
    const { container } = renderPage();
    await screen.findByTestId("release-results-empty");
    expect(container.firstChild).toMatchSnapshot();
  });

  it("has no accessibility violations", async () => {
    const { container } = renderPage();
    await screen.findByTestId("release-results-empty");
    expect(await axe(container)).toHaveNoViolations();
  });

  it("has no accessibility violations with download cards and package actions", async () => {
    vi.mocked(loadLatestAssets).mockResolvedValue([
      {
        release_name: "jdk-17",
        binary: {
          os: "linux",
          architecture: "x64",
          image_type: "jdk",
          package: {
            link: "https://example.com/jdk.tar.gz",
            name: "jdk.tar.gz",
            size: 1000000,
            checksum: "abc",
          },
        },
      },
    ]);
    const { container } = renderPage();
    await screen.findByTestId("quick-download-linux");
    expect(await axe(container)).toHaveNoViolations();
  });

  it("loads the latest LTS once when no filters are specified", async () => {
    url.value = "";
    renderPage();
    await waitFor(() =>
      expect(loadLatestAssets).toHaveBeenCalledExactlyOnceWith(
        25,
        "any",
        "any",
      ),
    );
    expect(
      screen.getByRole("button", { name: "JDK 25 - LTS" }),
    ).toHaveAttribute("aria-pressed", "true");
  });

  it("links setup-java to Adoptium's own GitHub Actions guide", async () => {
    renderPage();
    await screen.findByTestId("release-results-empty");
    expect(screen.getByRole("link", { name: "setup-java" })).toHaveAttribute(
      "href",
      "/installation/github-actions",
    );
    expect(
      screen.getByRole("link", { name: "setup-java" }),
    ).not.toHaveAttribute("target");
  });

  it("restores shared platform filters from the URL", async () => {
    url.value = "version=21&os=mac&arch=aarch64";
    renderPage();
    await waitFor(() =>
      expect(loadLatestAssets).toHaveBeenCalledWith(21, "mac", "aarch64"),
    );
    expect(screen.getByTestId("version-selector")).toHaveValue("21");
    expect(screen.getByTestId("os-selector")).toHaveValue("mac");
    expect(screen.getByTestId("arch-selector")).toHaveValue("aarch64");
  });

  it("keeps All Versions mode when selecting an LTS in the filter controls", async () => {
    renderPage();
    fireEvent.click(screen.getAllByTestId("version-tab")[0]);
    fireEvent.change(screen.getByTestId("version-selector"), {
      target: { value: "21" },
    });
    await waitFor(() =>
      expect(loadLatestAssets).toHaveBeenCalledWith(21, "any", "any"),
    );
    expect(new URLSearchParams(url.value).get("mode")).toBe("filter");
    expect(screen.getAllByTestId("version-tab")[0]).toHaveAttribute(
      "aria-pressed",
      "true",
    );
    expect(screen.getByTestId("release-filters-section")).toBeVisible();
  });

  it("resets platform filters when switching to an LTS shortcut", async () => {
    url.value = "version=17&os=linux&arch=aarch64&mode=filter";
    renderPage();
    fireEvent.click(screen.getByRole("button", { name: "JDK 21 - LTS" }));
    await waitFor(() =>
      expect(loadLatestAssets).toHaveBeenLastCalledWith(21, "any", "any"),
    );
    expect(new URLSearchParams(url.value).has("mode")).toBe(false);
    expect(
      screen.queryByTestId("release-filters-section"),
    ).not.toBeInTheDocument();
  });

  it("updates platform requests immediately", async () => {
    url.value = "version=25&mode=filter";
    renderPage();
    fireEvent.change(screen.getByTestId("os-selector"), {
      target: { value: "windows" },
    });
    fireEvent.change(screen.getByTestId("arch-selector"), {
      target: { value: "x64" },
    });
    await waitFor(() =>
      expect(loadLatestAssets).toHaveBeenLastCalledWith(25, "windows", "x64"),
    );
    expect(screen.getByTestId("arch-selector")).toHaveValue("x64");
  });

  it("selects All Versions for non-LTS releases", async () => {
    url.value = "version=26";
    renderPage();
    await waitFor(() =>
      expect(loadLatestAssets).toHaveBeenCalledWith(26, "any", "any"),
    );
    expect(screen.getByTestId("version-selector")).toHaveValue("26");
  });

  it.each(["latest", "any", "99"])(
    "normalizes the version parameter %s to the latest LTS",
    async (version) => {
      url.value = `version=${version}`;
      renderPage();
      await waitFor(() =>
        expect(loadLatestAssets).toHaveBeenCalledWith(25, "any", "any"),
      );
      if (version === "99") expect(screen.getByRole("status")).toBeVisible();
    },
  );

  it("explains unsupported platform parameters instead of issuing an invalid API request", async () => {
    url.value = "version=25&os=invalid-os&arch=invalid-arch&mode=filter";
    renderPage();
    await waitFor(() =>
      expect(loadLatestAssets).toHaveBeenCalledWith(25, "any", "any"),
    );
    expect(screen.getByRole("status")).toBeVisible();
    expect(screen.getByTestId("os-selector")).toHaveValue("any");
    expect(screen.getByTestId("arch-selector")).toHaveValue("any");
  });

  it("ignores stale requests after a newer version is selected", async () => {
    let resolveOld!: (assets: TemurinAssets) => void;
    let resolveNew!: (assets: TemurinAssets) => void;
    vi.mocked(loadLatestAssets)
      .mockReturnValueOnce(
        new Promise<TemurinAssets>((resolve) => {
          resolveOld = resolve;
        }),
      )
      .mockReturnValueOnce(
        new Promise<TemurinAssets>((resolve) => {
          resolveNew = resolve;
        }),
      );
    renderPage();
    fireEvent.click(screen.getByRole("button", { name: "JDK 21 - LTS" }));
    const current: TemurinAssets = [
      {
        release_name: "jdk-21-current",
        binary: {
          os: "linux",
          architecture: "x64",
          image_type: "jdk",
          package: {
            link: "https://example.com/jdk.tar.gz",
            name: "jdk.tar.gz",
            size: 1000000,
            checksum: "abc",
          },
        },
      },
    ];
    await act(async () => resolveNew(current));
    expect(screen.getByTestId("release-header-linux")).toHaveTextContent(
      "jdk-21-current",
    );
    await act(async () => resolveOld([]));
    expect(screen.getByTestId("release-header-linux")).toHaveTextContent(
      "jdk-21-current",
    );
  });

  it("shows a real request failure separately from an empty result and retries", async () => {
    const error = new Error("API unavailable");
    const logError = vi.spyOn(console, "error").mockImplementation(() => {});
    vi.mocked(loadLatestAssets)
      .mockRejectedValueOnce(error)
      .mockResolvedValueOnce([]);
    renderPage();
    const alert = await screen.findByRole("alert");
    expect(
      screen.queryByTestId("release-results-empty"),
    ).not.toBeInTheDocument();
    fireEvent.click(within(alert).getByRole("button"));
    await screen.findByTestId("release-results-empty");
    expect(loadLatestAssets).toHaveBeenCalledTimes(2);
    expect(logError).toHaveBeenCalledWith("Error fetching releases:", error);
  });

  it("responds to navigation-driven URL changes", async () => {
    renderPage();
    await act(async () => {
      url.value = "version=25&os=linux&arch=x64&mode=filter";
      url.listeners.forEach((listener) => listener());
    });
    await waitFor(() =>
      expect(loadLatestAssets).toHaveBeenLastCalledWith(25, "linux", "x64"),
    );
    expect(screen.getByTestId("version-selector")).toHaveValue("25");
  });
});
